const currency = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const statusLabel: Record<string, string> = { open: "Em aberto", partially_paid: "Parcial", paid: "Pago", overdue: "Vencido", cancelled: "Cancelado" };
const acceptedTypes = ["application/pdf", "image/jpeg", "image/png", "image/webp"] as const;
type InvoiceStatus = "open" | "partially_paid" | "paid" | "overdue" | "cancelled";
type BudgetType = "trade_events" | "branding_b2c";

const budgetTypeLabels: Record<BudgetType, string> = { trade_events: "Trade e Eventos", branding_b2c: "Branding / B2C" };
const costStatusLabels: Record<string, string> = { draft: "Rascunho", pending_approval: "Aguardando aprovação", approved: "Aprovado", rejected: "Rejeitado" };

function fileToBase64(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result).split(",")[1] ?? "");
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

type OperationalForecast = { id: number; type: "action" | "event" | "media_campaign"; label: string; startsAt: Date; estimatedCost: string; suppliers: { id: number; name: string }[] };

function OperationalForecastsPanel({ onUseForecast }: { onUseForecast: (forecast: OperationalForecast) => void }) {
  const forecasts = trpc.finance.operationForecasts.useQuery();
  const totalForecast = forecasts.data?.reduce((total, forecast) => total + Number(forecast.estimatedCost), 0) ?? 0;
  return <section className="mt-6 overflow-hidden rounded-2xl border border-border bg-card shadow-sm"><div className="flex flex-col gap-3 border-b border-border px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-display text-lg font-semibold text-foreground">Previsões operacionais</p><p className="mt-1 text-xs text-muted-foreground">Custos planejados de ações, eventos e mídias; eles não substituem o realizado nem geram nota automaticamente.</p></div><Badge variant="outline" className="w-fit border-primary/20 bg-primary/5 text-xs text-primary">{currency.format(totalForecast)} previsto</Badge></div>{forecasts.isLoading ? <p className="p-5 text-sm text-muted-foreground">Carregando previsões...</p> : forecasts.data?.length ? <div className="divide-y divide-border">{forecasts.data.map(forecast => <article key={`${forecast.type}-${forecast.id}`} className="flex flex-col gap-3 px-5 py-4 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-foreground">{forecast.label}</p><Badge className="border-0 bg-secondary text-[10px] text-foreground">{forecast.type === "action" ? "Ação" : forecast.type === "event" ? "Evento" : "Mídia"}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{new Date(forecast.startsAt).toLocaleDateString("pt-BR")} · {forecast.suppliers.length ? forecast.suppliers.map(supplier => supplier.name).join(", ") : "Fornecedor ainda não vinculado"}</p></div><div className="flex items-center gap-3"><span className="text-sm font-semibold text-foreground">{currency.format(Number(forecast.estimatedCost))}</span><Button size="sm" variant="outline" className="h-8 border-border text-xs" onClick={() => onUseForecast(forecast)}>Usar na nota</Button></div></article>)}</div> : <p className="p-5 text-sm text-muted-foreground">Não há custos previstos em ações, eventos ou mídias no momento.</p>}</section>;
}

function AnnualBudgetPlanner({ canWrite }: { canWrite: boolean }) {
  const utils = trpc.useUtils();
  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [amounts, setAmounts] = useState<Record<BudgetType, string>>({ trade_events: "", branding_b2c: "" });
  const [notes, setNotes] = useState<Record<BudgetType, string>>({ trade_events: "", branding_b2c: "" });
  const [replaceExisting, setReplaceExisting] = useState<Record<BudgetType, boolean>>({ trade_events: false, branding_b2c: false });
  const summary = trpc.budgets.annualSummary.useQuery({ year: Number(year) });
  const saveAnnual = trpc.budgets.saveAnnualBudget.useMutation({ onSuccess: (_, variables) => { toast.success("Verba anual distribuída entre as 12 competências."); utils.budgets.annualSummary.invalidate({ year: variables.year }); utils.budgets.listBudgets.invalidate(); utils.budgets.summary.invalidate(); setAmounts(current => ({ ...current, [variables.budgetType]: "" })); setReplaceExisting(current => ({ ...current, [variables.budgetType]: false })); }, onError: error => toast.error(error.message) });
  return <section className="mt-6 rounded-2xl border border-primary/20 bg-primary/[0.03] p-5 shadow-sm"><div className="flex flex-col gap-3 border-b border-primary/10 pb-4 sm:flex-row sm:items-end sm:justify-between"><div><div className="flex items-center gap-2"><Landmark className="h-4 w-4 text-primary" /><p className="font-semibold text-foreground">Planejamento anual de verba</p></div><p className="mt-1 max-w-2xl text-xs text-muted-foreground">Defina a estimativa anual por categoria. O valor é distribuído pelas 12 competências para facilitar o controle mensal do planejado e do realizado.</p></div><div><Label htmlFor="annual-budget-year" className="text-xs">Ano</Label><Input id="annual-budget-year" type="number" min="2020" max="2100" value={year} onChange={event => setYear(event.target.value)} className="mt-1 h-9 w-28 bg-background" /></div></div><div className="mt-4 grid gap-4 lg:grid-cols-2">{(["trade_events", "branding_b2c"] as BudgetType[]).map(type => { const annual = summary.data?.find(item => item.budgetType === type); const proposed = Number(amounts[type] || 0); const hasExisting = Boolean(annual?.configuredMonths); return <article key={type} className="rounded-xl border border-border bg-card p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold text-foreground">{budgetTypeLabels[type]}</p><p className="mt-1 text-xs text-muted-foreground">{annual?.configuredMonths ?? 0} de 12 meses configurados · realizado: {currency.format(annual?.realized ?? 0)}</p></div><span className="text-sm font-semibold text-primary">{currency.format(annual?.planned ?? 0)}</span></div><div className="mt-3 grid gap-2 sm:grid-cols-2"><div><Label htmlFor={`annual-budget-${type}`} className="text-xs">Verba anual</Label><Input id={`annual-budget-${type}`} type="number" min="0" step="0.01" value={amounts[type]} onChange={event => setAmounts(current => ({ ...current, [type]: event.target.value }))} placeholder="0,00" className="mt-1 h-9 bg-background" /></div><div className="rounded-md bg-secondary px-3 py-2"><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Estimativa mensal</p><p className="mt-1 text-sm font-semibold text-foreground">{currency.format(proposed / 12)}</p></div></div><Input aria-label={`Observações anuais para ${budgetTypeLabels[type]}`} value={notes[type]} onChange={event => setNotes(current => ({ ...current, [type]: event.target.value }))} placeholder="Observação anual opcional" className="mt-2 h-8 bg-background text-xs" />{hasExisting && <label className="mt-3 flex items-start gap-2 text-xs text-muted-foreground"><input type="checkbox" checked={replaceExisting[type]} onChange={event => setReplaceExisting(current => ({ ...current, [type]: event.target.checked }))} className="mt-0.5 h-4 w-4 accent-primary" /> Confirmo a substituição das verbas mensais deste ano</label>}{canWrite && <Button type="button" size="sm" disabled={saveAnnual.isPending || proposed <= 0 || hasExisting && !replaceExisting[type]} onClick={() => saveAnnual.mutate({ year: Number(year), budgetType: type, annualAmount: proposed, notes: notes[type] || undefined, replaceExisting: replaceExisting[type] })} className="mt-3 h-8 w-full bg-primary text-xs hover:bg-primary/90">Distribuir verba anual</Button>}</article>; })}</div></section>;
}

function BudgetAndCostsPanel({ canWrite }: { canWrite: boolean }) {
  const utils = trpc.useUtils();
  const currentMonth = new Date().toISOString().slice(0, 7);
  const [month, setMonth] = useState(currentMonth);
  const [budgetAmounts, setBudgetAmounts] = useState<Record<BudgetType, string>>({ trade_events: "", branding_b2c: "" });
  const [budgetNotes, setBudgetNotes] = useState<Record<BudgetType, string>>({ trade_events: "", branding_b2c: "" });
  const [showCostForm, setShowCostForm] = useState(false);
  const [costForm, setCostForm] = useState({ operationId: "", budgetType: "trade_events" as BudgetType, investmentBase: "0", permitCost: "0", storeCost: "0", otherCosts: "0", notes: "", submitForApproval: false });
  const summary = trpc.budgets.summary.useQuery({ month });
  const savedBudgets = trpc.budgets.listBudgets.useQuery({ month });
  const costs = trpc.budgets.listCosts.useQuery();
  const operations = trpc.budgets.operationOptions.useQuery();
  const saveBudget = trpc.budgets.saveBudget.useMutation({ onSuccess: () => { toast.success("Orçamento mensal salvo."); utils.budgets.listBudgets.invalidate({ month }); utils.budgets.summary.invalidate({ month }); }, onError: error => toast.error(error.message) });
  const deleteBudget = trpc.budgets.deleteBudget.useMutation({ onSuccess: () => { toast.success("Verba mensal excluída com segurança."); utils.budgets.listBudgets.invalidate({ month }); utils.budgets.summary.invalidate({ month }); utils.budgets.annualSummary.invalidate(); }, onError: error => toast.error(error.message) });
  const upsertCost = trpc.budgets.upsertCost.useMutation({ onSuccess: () => { toast.success("Custo operacional salvo."); utils.budgets.listCosts.invalidate(); utils.budgets.summary.invalidate({ month }); setShowCostForm(false); setCostForm({ operationId: "", budgetType: "trade_events", investmentBase: "0", permitCost: "0", storeCost: "0", otherCosts: "0", notes: "", submitForApproval: false }); }, onError: error => toast.error(error.message) });
  const reviewCost = trpc.budgets.reviewCost.useMutation({ onSuccess: (_, variables) => { toast.success(variables.status === "approved" ? "Custo aprovado e considerado no orçamento." : "Custo rejeitado."); utils.budgets.listCosts.invalidate(); utils.budgets.summary.invalidate({ month }); }, onError: error => toast.error(error.message) });
  const deleteCost = trpc.budgets.deleteCost.useMutation({ onSuccess: () => { toast.success("Custo operacional excluído com segurança."); utils.budgets.listCosts.invalidate(); utils.budgets.summary.invalidate({ month }); utils.budgets.annualSummary.invalidate(); }, onError: error => toast.error(error.message) });
  const totalBudget = summary.data?.reduce((sum, row) => sum + row.total, 0) ?? 0;
  const totalRealized = summary.data?.reduce((sum, row) => sum + row.realized, 0) ?? 0;
  const totalAvailable = summary.data?.reduce((sum, row) => sum + row.available, 0) ?? 0;
  const { can } = useEffectivePermissions();
  const canApprove = can("finance.update");
  const canDelete = can("finance.delete");
  const storedFor = (budgetType: BudgetType) => savedBudgets.data?.find(item => item.budgetType === budgetType);
  const storedValue = (budgetType: BudgetType) => budgetAmounts[budgetType] || (storedFor(budgetType) ? String(Number(storedFor(budgetType)?.totalAmount ?? 0)) : "");
  const submitCost = (event: FormEvent) => { event.preventDefault(); upsertCost.mutate({ operationId: Number(costForm.operationId), budgetType: costForm.budgetType, investmentBase: Number(costForm.investmentBase), permitCost: Number(costForm.permitCost), storeCost: Number(costForm.storeCost), otherCosts: Number(costForm.otherCosts), notes: costForm.notes || undefined, submitForApproval: costForm.submitForApproval }); };

  return <section className="mt-6 space-y-5"><div className="flex flex-col gap-3 rounded-2xl border border-border bg-card p-5 shadow-sm sm:flex-row sm:items-end sm:justify-between"><div><div className="flex items-center gap-2"><CircleDollarSign className="h-4 w-4 text-primary" /><p className="font-display text-lg font-semibold text-foreground">Orçamento vivo</p></div><p className="mt-1 text-xs text-muted-foreground">Apenas custos aprovados compõem o valor realizado da competência.</p></div><div><Label htmlFor="budget-month" className="text-xs">Competência</Label><Input id="budget-month" type="month" value={month} onChange={event => { setMonth(event.target.value); setBudgetAmounts({ trade_events: "", branding_b2c: "" }); setBudgetNotes({ trade_events: "", branding_b2c: "" }); }} className="mt-1 h-9 w-40" /></div></div>
    <div className="grid gap-3 sm:grid-cols-3"><article className="rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-[11px] font-semibold uppercase tracking-[0.13em] text-muted-foreground">Verba total</p><p className="mt-2 text-2xl font-semibold tracking-tight text-foreground">{currency.format(totalBudget)}</p><p className="mt-1 text-xs text-muted-foreground">Orçamentos configurados no mês</p></article><article className="rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-[11px] font-semibold uppercase tracking-[0.13em] text-muted-foreground">Valor realizado</p><p className="mt-2 text-2xl font-semibold tracking-tight text-primary">{currency.format(totalRealized)}</p><p className="mt-1 text-xs text-muted-foreground">Custos operacionais aprovados</p></article><article className="rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-[11px] font-semibold uppercase tracking-[0.13em] text-muted-foreground">Saldo disponível</p><p className={`mt-2 text-2xl font-semibold tracking-tight ${totalAvailable < 0 ? "text-destructive" : "text-foreground"}`}>{currency.format(totalAvailable)}</p><p className="mt-1 text-xs text-muted-foreground">Verba total menos valor realizado</p></article></div>
    <div className="grid gap-5 xl:grid-cols-[0.95fr_1.35fr]"><div className="rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="font-semibold text-foreground">Configuração de verba</p><p className="mt-1 text-xs text-muted-foreground">Defina os limites mensais por tipo de verba.</p><div className="mt-4 space-y-4">{(["trade_events", "branding_b2c"] as BudgetType[]).map(type => { const row = summary.data?.find(item => item.budgetType === type); const savedRow = storedFor(type); return <div key={type} className="rounded-xl bg-secondary p-3"><div className="flex items-center justify-between"><Label htmlFor={`budget-${type}`} className="text-sm font-semibold">{budgetTypeLabels[type]}</Label>{row?.hasBudget && <span className="text-[10px] font-semibold text-primary">Configurado</span>}</div><Input id={`budget-${type}`} type="number" min="0" step="0.01" value={storedValue(type)} onChange={event => setBudgetAmounts({ ...budgetAmounts, [type]: event.target.value })} placeholder="0,00" className="mt-2 bg-background" /><Input aria-label={`Observações para ${budgetTypeLabels[type]}`} value={budgetNotes[type] || storedFor(type)?.notes || ""} onChange={event => setBudgetNotes({ ...budgetNotes, [type]: event.target.value })} placeholder="Observação opcional" className="mt-2 h-8 bg-background text-xs" />{canWrite && <Button type="button" size="sm" disabled={saveBudget.isPending || deleteBudget.isPending || !storedValue(type)} onClick={() => saveBudget.mutate({ month, budgetType: type, totalAmount: Number(storedValue(type)), notes: budgetNotes[type] || storedFor(type)?.notes || undefined })} className="mt-2 h-8 w-full bg-primary text-xs hover:bg-primary/90">Salvar verba</Button>}{canDelete && savedRow && <Button type="button" size="sm" variant="outline" disabled={deleteBudget.isPending} onClick={() => { if (window.confirm(`Excluir a verba mensal de ${budgetTypeLabels[type]} da competência ${month}? A ação será auditada.`)) deleteBudget.mutate({ id: savedRow.id }); }} className="mt-2 h-8 w-full border-destructive/30 text-xs text-destructive hover:bg-destructive/10">Excluir verba</Button>}</div>; })}</div></div>
      <div className="rounded-2xl border border-border bg-card shadow-sm"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><p className="font-semibold text-foreground">Custos de operação</p><p className="mt-1 text-xs text-muted-foreground">Base, alvará, loja e demais custos vinculados a uma operação.</p></div>{canWrite && <Button size="sm" onClick={() => setShowCostForm(value => !value)} className="h-8 bg-primary text-xs hover:bg-primary/90"><Plus className="mr-1.5 h-3.5 w-3.5" /> Custo</Button>}</div>{showCostForm && <form onSubmit={submitCost} className="grid gap-3 border-b border-border bg-secondary p-4 md:grid-cols-3"><div className="md:col-span-2"><Label htmlFor="cost-operation" className="text-xs">Operação</Label><select id="cost-operation" required value={costForm.operationId} onChange={event => setCostForm({ ...costForm, operationId: event.target.value })} className="mt-1 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecionar operação</option>{operations.data?.map(operation => <option key={operation.id} value={operation.id}>{operation.name} · {new Date(operation.startsAt).toLocaleDateString("pt-BR")}</option>)}</select></div><div><Label htmlFor="cost-budget-type" className="text-xs">Verba</Label><select id="cost-budget-type" value={costForm.budgetType} onChange={event => setCostForm({ ...costForm, budgetType: event.target.value as BudgetType })} className="mt-1 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="trade_events">Trade e Eventos</option><option value="branding_b2c">Branding / B2C</option></select></div><div><Label htmlFor="cost-base" className="text-xs">Investimento base</Label><Input id="cost-base" type="number" min="0" step="0.01" value={costForm.investmentBase} onChange={event => setCostForm({ ...costForm, investmentBase: event.target.value })} className="mt-1 h-9 bg-background" /></div><div><Label htmlFor="cost-permit" className="text-xs">Custo de alvará</Label><Input id="cost-permit" type="number" min="0" step="0.01" value={costForm.permitCost} onChange={event => setCostForm({ ...costForm, permitCost: event.target.value })} className="mt-1 h-9 bg-background" /></div><div><Label htmlFor="cost-store" className="text-xs">Custo em loja</Label><Input id="cost-store" type="number" min="0" step="0.01" value={costForm.storeCost} onChange={event => setCostForm({ ...costForm, storeCost: event.target.value })} className="mt-1 h-9 bg-background" /></div><div><Label htmlFor="cost-other" className="text-xs">Outros custos</Label><Input id="cost-other" type="number" min="0" step="0.01" value={costForm.otherCosts} onChange={event => setCostForm({ ...costForm, otherCosts: event.target.value })} className="mt-1 h-9 bg-background" /></div><div className="md:col-span-2"><Label htmlFor="cost-notes" className="text-xs">Observações</Label><Input id="cost-notes" value={costForm.notes} onChange={event => setCostForm({ ...costForm, notes: event.target.value })} className="mt-1 h-9 bg-background" /></div><label className="flex items-end gap-2 pb-2 text-xs font-medium text-foreground"><input type="checkbox" checked={costForm.submitForApproval} onChange={event => setCostForm({ ...costForm, submitForApproval: event.target.checked })} className="h-4 w-4 accent-primary" /> Enviar para aprovação</label><Button type="submit" disabled={upsertCost.isPending} className="h-9 self-end bg-primary hover:bg-primary/90">Salvar custo</Button></form>}<div className="divide-y divide-border">{costs.isLoading ? <p className="p-5 text-sm text-muted-foreground">Carregando custos...</p> : costs.data?.length ? costs.data.map(cost => <div key={cost.id} className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-foreground">{cost.operationName}</p><Badge className={`border-0 text-[10px] ${cost.status === "approved" ? "bg-primary/10 text-primary" : cost.status === "rejected" ? "bg-destructive/10 text-destructive" : "bg-secondary text-foreground"}`}>{costStatusLabels[cost.status]}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{budgetTypeLabels[cost.budgetType]} · {new Date(cost.operationStartsAt).toLocaleDateString("pt-BR")}{cost.notes ? ` · ${cost.notes}` : ""}</p></div><div className="flex items-center gap-2"><span className="text-sm font-semibold text-foreground">{currency.format(cost.total)}</span>{canApprove && cost.status === "pending_approval" && <><Button size="sm" variant="outline" disabled={reviewCost.isPending || deleteCost.isPending} onClick={() => reviewCost.mutate({ costId: cost.id, status: "rejected" })} className="h-8 border-border text-xs">Rejeitar</Button><Button size="sm" disabled={reviewCost.isPending || deleteCost.isPending} onClick={() => reviewCost.mutate({ costId: cost.id, status: "approved" })} className="h-8 bg-primary text-xs hover:bg-primary/90"><ClipboardCheck className="mr-1 h-3.5 w-3.5" /> Aprovar</Button></>}{canDelete && ["draft", "pending_approval"].includes(cost.status) && <Button size="sm" variant="outline" disabled={deleteCost.isPending} onClick={() => { if (window.confirm(`Excluir o custo operacional de ${cost.operationName}? A ação será auditada e não afeta custos aprovados.`)) deleteCost.mutate({ costId: cost.id }); }} className="h-8 border-destructive/30 text-xs text-destructive hover:bg-destructive/10"><Trash2 className="mr-1 h-3.5 w-3.5" />Excluir</Button>}</div></div>) : <div className="p-8 text-center"><CircleDollarSign className="mx-auto h-5 w-5 text-muted-foreground" /><p className="mt-2 text-sm font-medium text-foreground">Ainda não há custos operacionais</p><p className="mt-1 text-xs text-muted-foreground">Vincule custos às operações para acompanhar o consumo de verba.</p></div>}</div></div></div>
  </section>;
}

function CorporateFinancePanel({ canWrite }: { canWrite: boolean }) {
  const utils = trpc.useUtils();
  const { can } = useEffectivePermissions();
  const canApprove = can("finance.approve");
  const [year, setYear] = useState(String(new Date().getFullYear()));
  const [activeView, setActiveView] = useState<"overview" | "budget" | "orders">("overview");
  const [showOrder, setShowOrder] = useState(false);
  const [orderForm, setOrderForm] = useState({ orderNumber: "", supplierId: "", companyId: "", fiscalEntityId: "", description: "", kind: "service" as "product" | "service" | "media" | "other", quantity: "1", unit: "unidade", unitPrice: "", expectedDeliveryOn: "", notes: "" });
  const dimensions = trpc.finance.financeDimensions.useQuery();
  const selectedCompany = dimensions.data?.companies.find(company => String(company.id) === orderForm.companyId);
  const snapshot = trpc.finance.budgetSnapshot.useQuery({ year: Number(year) });
  const cash = trpc.finance.cashAnalysis.useQuery({ year: Number(year) });
  const orders = trpc.finance.listPurchaseOrders.useQuery();
  const createOrder = trpc.finance.createPurchaseOrder.useMutation({ onSuccess: () => { toast.success("Pedido de compra registrado e enviado para o fluxo financeiro."); utils.finance.listPurchaseOrders.invalidate(); utils.finance.cashAnalysis.invalidate({ year: Number(year) }); setShowOrder(false); setOrderForm({ orderNumber: "", supplierId: "", companyId: "", fiscalEntityId: "", description: "", kind: "service", quantity: "1", unit: "unidade", unitPrice: "", expectedDeliveryOn: "", notes: "" }); }, onError: error => toast.error(error.message) });
  const reviewOrder = trpc.finance.reviewPurchaseOrder.useMutation({ onSuccess: () => { toast.success("Status do pedido atualizado."); utils.finance.listPurchaseOrders.invalidate(); utils.finance.cashAnalysis.invalidate({ year: Number(year) }); }, onError: error => toast.error(error.message) });
  const cashTotals = cash.data && "totals" in cash.data ? cash.data.totals : undefined;
  const submitOrder = (event: FormEvent) => { event.preventDefault(); createOrder.mutate({ orderNumber: orderForm.orderNumber, supplierId: Number(orderForm.supplierId), companyId: orderForm.companyId ? Number(orderForm.companyId) : null, fiscalEntityId: orderForm.fiscalEntityId ? Number(orderForm.fiscalEntityId) : null, expectedDeliveryOn: orderForm.expectedDeliveryOn || null, notes: orderForm.notes || undefined, items: [{ kind: orderForm.kind, description: orderForm.description, quantity: Number(orderForm.quantity), unit: orderForm.unit, unitPrice: Number(orderForm.unitPrice) }] }); };
  return <section className="mt-6 overflow-hidden rounded-2xl border border-primary/20 bg-primary/[0.03] shadow-sm"><div className="flex flex-col gap-4 border-b border-primary/10 px-5 py-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex items-center gap-2"><BarChart3 className="h-4 w-4 text-primary" /><p className="font-display text-lg font-semibold text-foreground">Financeiro corporativo</p></div><p className="mt-1 max-w-3xl text-xs leading-5 text-muted-foreground">Orçamento anual, pedidos, realizado e impacto no caixa. O núcleo começa no Trade, mas está preparado para todo o setor.</p></div><div className="flex items-center gap-2"><Label htmlFor="corporate-finance-year" className="text-xs">Ano</Label><Input id="corporate-finance-year" type="number" min="2020" max="2200" value={year} onChange={event => setYear(event.target.value)} className="h-9 w-24 bg-background" />{canWrite && <Button size="sm" onClick={() => setShowOrder(true)} className="h-9 bg-primary text-xs hover:bg-primary/90"><ShoppingCart className="mr-1.5 h-3.5 w-3.5" /> Novo pedido</Button>}</div></div><div className="flex flex-wrap gap-2 border-b border-border bg-card px-5 py-3"><Button size="sm" variant={activeView === "overview" ? "default" : "outline"} onClick={() => setActiveView("overview")} className="h-8 text-xs"><TrendingUp className="mr-1.5 h-3.5 w-3.5" /> Análise de caixa</Button><Button size="sm" variant={activeView === "budget" ? "default" : "outline"} onClick={() => setActiveView("budget")} className="h-8 text-xs">Planejamento mensal</Button><Button size="sm" variant={activeView === "orders" ? "default" : "outline"} onClick={() => setActiveView("orders")} className="h-8 text-xs">Pedidos de compra</Button></div>{activeView === "overview" && <div className="p-5"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><article className="rounded-xl border border-border bg-card p-4"><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Orçado</p><p className="mt-2 text-xl font-semibold text-foreground">{currency.format(cashTotals?.planned ?? 0)}</p></article><article className="rounded-xl border border-border bg-card p-4"><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Comprometido</p><p className="mt-2 text-xl font-semibold text-foreground">{currency.format(cashTotals?.committed ?? 0)}</p></article><article className="rounded-xl border border-border bg-card p-4"><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Realizado</p><p className="mt-2 text-xl font-semibold text-primary">{currency.format(cashTotals?.realized ?? 0)}</p></article><article className="rounded-xl border border-border bg-card p-4"><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Pago</p><p className="mt-2 text-xl font-semibold text-foreground">{currency.format(cashTotals?.paid ?? 0)}</p></article><article className={`rounded-xl border p-4 ${Number(cashTotals?.balance ?? 0) < 0 ? "border-destructive/30 bg-destructive/5" : "border-border bg-card"}`}><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Saldo projetado</p><p className="mt-2 text-xl font-semibold text-foreground">{currency.format(cashTotals?.balance ?? 0)}</p></article></div><div className="mt-5 overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[760px] text-left text-xs"><thead className="bg-secondary text-[10px] uppercase tracking-wide text-muted-foreground"><tr><th className="px-3 py-2">Mês</th><th className="px-3 py-2 text-right">Orçado</th><th className="px-3 py-2 text-right">Comprometido</th><th className="px-3 py-2 text-right">Realizado</th><th className="px-3 py-2 text-right">Pago</th><th className="px-3 py-2 text-right">Pendente</th><th className="px-3 py-2 text-right">Saldo</th></tr></thead><tbody className="divide-y divide-border">{cash.data && "monthly" in cash.data ? cash.data.monthly.map(row => <tr key={row.month}><td className="px-3 py-2 font-medium">{new Date(2020, row.month - 1, 1).toLocaleDateString("pt-BR", { month: "short" })}</td><td className="px-3 py-2 text-right">{currency.format(row.planned)}</td><td className="px-3 py-2 text-right">{currency.format(row.committed)}</td><td className="px-3 py-2 text-right">{currency.format(row.realized)}</td><td className="px-3 py-2 text-right">{currency.format(row.paid)}</td><td className="px-3 py-2 text-right text-accent-foreground">{currency.format(row.pending)}</td><td className={`px-3 py-2 text-right font-semibold ${row.balance < 0 ? "text-destructive" : "text-foreground"}`}>{currency.format(row.balance)}</td></tr>) : null}</tbody></table></div></div>}{activeView === "budget" && <div className="p-5"><div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold text-foreground">Orçamento anual e memória de cálculo</p><p className="mt-1 text-xs text-muted-foreground">As linhas são organizadas por empresa, divisão, setor, meio, conta e competência mensal.</p></div><Badge variant="outline" className="w-fit text-xs">{snapshot.data?.lines.length ?? 0} linhas · {snapshot.data?.plans.length ?? 0} planos</Badge></div><div className="mt-4 overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[960px] text-left text-xs"><thead className="bg-secondary text-[10px] uppercase tracking-wide text-muted-foreground"><tr><th className="px-3 py-2">Linha orçamentária</th>{Array.from({ length: 12 }, (_, index) => <th key={index} className="px-3 py-2 text-right">{new Date(2020, index, 1).toLocaleDateString("pt-BR", { month: "short" })}</th>)}<th className="px-3 py-2 text-right">Anual</th></tr></thead><tbody className="divide-y divide-border">{snapshot.data?.lines.map(line => <tr key={line.id}><td className="px-3 py-2 font-medium">Conta #{line.accountId ?? "—"} · Meio #{line.mediumId ?? "—"}</td>{Array.from({ length: 12 }, (_, index) => <td key={index} className="px-3 py-2 text-right">{currency.format(Number(line.months.find(month => month.month === index + 1)?.plannedAmount ?? 0))}</td>)}<td className="px-3 py-2 text-right font-semibold">{currency.format(Number(line.annualAmount))}</td></tr>)}</tbody></table>{!snapshot.data?.lines.length && <p className="p-8 text-center text-sm text-muted-foreground">Crie o primeiro plano e as linhas mensais para reproduzir a memória de cálculo.</p>}</div></div>}{activeView === "orders" && <div className="p-5"><div className="flex items-center justify-between"><div><p className="font-semibold text-foreground">Pedidos de compra</p><p className="mt-1 text-xs text-muted-foreground">Registre o número da ordem, fornecedor, item e valor. A aprovação passa a comprometer o orçamento.</p></div><Badge variant="outline" className="text-xs">{orders.data?.length ?? 0} pedidos</Badge></div><div className="mt-4 divide-y divide-border rounded-xl border border-border bg-card">{orders.data?.map(order => <article key={order.id} className="flex flex-col gap-3 px-4 py-4 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-foreground">OC {order.orderNumber}</p><Badge variant="outline" className="text-[10px]">{order.status}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{order.supplierName} · {order.items.length} item(ns) · {currency.format(Number(order.totalAmount))}{order.expectedDeliveryOn ? ` · previsão ${new Date(`${order.expectedDeliveryOn}T12:00:00`).toLocaleDateString("pt-BR")}` : ""}</p></div>{canApprove && (order.status === "draft" || order.status === "pending_approval") && <div className="flex gap-2"><Button size="sm" className="h-8 bg-primary text-xs" onClick={() => reviewOrder.mutate({ purchaseOrderId: order.id, status: "approved" })}>Aprovar</Button><Button size="sm" variant="outline" className="h-8 text-xs" onClick={() => reviewOrder.mutate({ purchaseOrderId: order.id, status: "rejected" })}>Rejeitar</Button></div>}</article>)}{!orders.data?.length && <p className="p-8 text-center text-sm text-muted-foreground">Nenhum pedido de compra registrado.</p>}</div></div>}{showOrder && <Dialog open={showOrder} onOpenChange={setShowOrder}><DialogContent className="max-w-2xl"><DialogHeader><DialogTitle>Novo pedido de compra</DialogTitle><DialogDescription>O pedido é simples: ordem externa, fornecedor, item, valor e previsão. Depois ele pode ser aprovado para entrar na análise de caixa.</DialogDescription></DialogHeader><form onSubmit={submitOrder} className="grid gap-4 md:grid-cols-2"><div><Label htmlFor="po-number">Número da ordem</Label><Input id="po-number" required value={orderForm.orderNumber} onChange={event => setOrderForm({ ...orderForm, orderNumber: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="po-supplier">Fornecedor</Label><select id="po-supplier" required value={orderForm.supplierId} onChange={event => setOrderForm({ ...orderForm, supplierId: event.target.value })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecionar</option>{dimensions.data?.offerings.map(item => <option key={item.offering.id} value={item.offering.supplierId}>{item.supplierName} · {item.offering.name}</option>)}</select></div><div><Label htmlFor="po-company">Empresa operacional</Label><select id="po-company" value={orderForm.companyId} onChange={event => setOrderForm({ ...orderForm, companyId: event.target.value, fiscalEntityId: "" })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecionar</option>{dimensions.data?.companies.map(company => <option key={company.id} value={company.id}>{company.name} · {company.code}</option>)}</select></div><div><Label htmlFor="po-fiscal-entity">Empresa fiscal / CNPJ</Label><select id="po-fiscal-entity" value={orderForm.fiscalEntityId} onChange={event => setOrderForm({ ...orderForm, fiscalEntityId: event.target.value })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecionar</option>{dimensions.data?.fiscalEntities.filter(item => !selectedCompany?.providerId || item.fiscalEntity.providerId === selectedCompany.providerId).map(item => <option key={item.fiscalEntity.id} value={item.fiscalEntity.id}>{item.fiscalEntity.name} · {item.fiscalEntity.cnpj}{item.providerName ? ` · ${item.providerName}` : ""}</option>)}</select></div><div className="md:col-span-2"><Label htmlFor="po-description">Item</Label><Input id="po-description" required value={orderForm.description} onChange={event => setOrderForm({ ...orderForm, description: event.target.value })} placeholder="Ex.: impressão de panfletos, diária de promotor, inserção de mídia" className="mt-1.5" /></div><div><Label htmlFor="po-kind">Natureza</Label><select id="po-kind" value={orderForm.kind} onChange={event => setOrderForm({ ...orderForm, kind: event.target.value as typeof orderForm.kind })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="service">Serviço</option><option value="product">Produto</option><option value="media">Mídia</option><option value="other">Outro</option></select></div><div><Label htmlFor="po-unit">Unidade</Label><Input id="po-unit" value={orderForm.unit} onChange={event => setOrderForm({ ...orderForm, unit: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="po-quantity">Quantidade</Label><Input id="po-quantity" required type="number" min="0.01" step="0.01" value={orderForm.quantity} onChange={event => setOrderForm({ ...orderForm, quantity: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="po-unit-price">Valor unitário</Label><Input id="po-unit-price" required type="number" min="0" step="0.01" value={orderForm.unitPrice} onChange={event => setOrderForm({ ...orderForm, unitPrice: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="po-delivery">Previsão de entrega/vencimento</Label><Input id="po-delivery" type="date" value={orderForm.expectedDeliveryOn} onChange={event => setOrderForm({ ...orderForm, expectedDeliveryOn: event.target.value })} className="mt-1.5" /></div><div className="md:col-span-2"><Label htmlFor="po-notes">Observações</Label><Textarea id="po-notes" value={orderForm.notes} onChange={event => setOrderForm({ ...orderForm, notes: event.target.value })} className="mt-1.5" /></div><div className="flex justify-end gap-2 md:col-span-2"><Button type="button" variant="outline" onClick={() => setShowOrder(false)}>Cancelar</Button><Button type="submit" disabled={createOrder.isPending} className="bg-primary hover:bg-primary/90">{createOrder.isPending ? "Salvando..." : "Salvar pedido"}</Button></div></form></DialogContent></Dialog>}</section>;
}

function InvoicesPaymentsPanel() {
  const utils = trpc.useUtils();
  const { can } = useEffectivePermissions();
  const canDelete = can("finance.delete");
  const canCreateTask = can("tasks.create");
  const invoices = trpc.finance.listInvoices.useQuery(undefined, { staleTime: 10_000 });
  const payments = trpc.finance.listPayments.useQuery(undefined, { staleTime: 10_000 });
  const deleteInvoice = trpc.finance.deleteInvoice.useMutation({ onSuccess: async () => { toast.success("Nota fiscal excluída com segurança."); await Promise.all([utils.finance.listInvoices.invalidate(), utils.finance.listBillings.invalidate(), utils.finance.listSupplierContracts.invalidate()]); }, onError: error => toast.error(error.message) });
  const deletePayment = trpc.finance.deletePayment.useMutation({ onSuccess: async () => { toast.success("Pagamento removido e status recalculado."); await Promise.all([utils.finance.listPayments.invalidate(), utils.finance.listInvoices.invalidate(), utils.finance.listBillings.invalidate()]); }, onError: error => toast.error(error.message) });
  const invoiceRows = invoices.data ?? [];
  const paymentRows = payments.data ?? [];
  return <section className="mt-6 grid gap-5 xl:grid-cols-2">
    <div className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><p className="font-display text-lg font-semibold text-foreground">Notas fiscais</p><p className="mt-1 text-xs text-muted-foreground">Exclusão disponível apenas para notas abertas, sem pagamentos ou comprovantes.</p></div><Badge variant="outline" className="text-xs">{invoiceRows.length}</Badge></div><div className="divide-y divide-border">{invoices.isLoading ? <p className="p-5 text-sm text-muted-foreground">Carregando notas...</p> : invoiceRows.length ? invoiceRows.map(invoice => <article key={invoice.id} className="flex flex-col gap-3 px-5 py-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-foreground">NF {invoice.invoiceNumber}</p><Badge variant="outline" className="text-[10px]">{statusLabel[invoice.status] ?? invoice.status}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{invoice.supplierName} · {currency.format(Number(invoice.amount))} · vencimento {new Date(`${invoice.dueDate}T12:00:00`).toLocaleDateString("pt-BR")}</p><p className="mt-1 text-xs text-muted-foreground">Pago: {currency.format(Number(invoice.totalPaid))} · {invoice.attachedDocuments.length ? `${invoice.attachedDocuments.length} comprovante(s)` : "sem comprovante"}</p></div><div className="flex shrink-0 items-center gap-2">{canCreateTask ? <ContextTaskDialog entityType="invoice" entityId={invoice.id} entityName={`NF ${invoice.invoiceNumber}`} defaultDescription={`Acompanhar a nota fiscal ${invoice.invoiceNumber} do fornecedor ${invoice.supplierName}.`} /> : null}{canDelete && invoice.status === "open" && Number(invoice.totalPaid) === 0 && invoice.attachedDocuments.length === 0 ? <Button type="button" variant="outline" size="icon" className="rounded-lg border-destructive/30 text-destructive hover:bg-destructive/10" disabled={deleteInvoice.isPending} aria-label={`Excluir NF ${invoice.invoiceNumber}`} onClick={() => { if (window.confirm(`Excluir a nota fiscal NF ${invoice.invoiceNumber}? Esta ação é permanente e será auditada.`)) deleteInvoice.mutate({ id: invoice.id }); }}><Trash2 className="h-4 w-4" /></Button> : null}</div></div></article>) : <p className="p-8 text-center text-sm text-muted-foreground">Nenhuma nota fiscal registrada.</p>}</div></div>
    <div className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><p className="font-display text-lg font-semibold text-foreground">Pagamentos</p><p className="mt-1 text-xs text-muted-foreground">A remoção recalcula o status da nota e da competência vinculada.</p></div><Badge variant="outline" className="text-xs">{paymentRows.length}</Badge></div><div className="divide-y divide-border">{payments.isLoading ? <p className="p-5 text-sm text-muted-foreground">Carregando pagamentos...</p> : paymentRows.length ? paymentRows.map(payment => <article key={payment.id} className="flex items-center justify-between gap-3 px-5 py-4"><div className="min-w-0"><p className="font-semibold text-foreground">NF {payment.invoiceNumber}</p><p className="mt-1 text-xs text-muted-foreground">{payment.supplierName} · {new Date(payment.paidAt).toLocaleDateString("pt-BR")} · {payment.method}</p><p className="mt-1 text-xs text-muted-foreground">{payment.reference || "Sem referência"}</p></div><div className="flex shrink-0 items-center gap-3"><p className="text-sm font-semibold text-foreground">{currency.format(Number(payment.amount))}</p>{canDelete ? <Button type="button" variant="outline" size="icon" className="rounded-lg border-destructive/30 text-destructive hover:bg-destructive/10" disabled={deletePayment.isPending} aria-label={`Excluir pagamento da NF ${payment.invoiceNumber}`} onClick={() => { if (window.confirm(`Excluir o pagamento de ${currency.format(Number(payment.amount))} da NF ${payment.invoiceNumber}? O status será recalculado e a ação será auditada.`)) deletePayment.mutate({ id: payment.id }); }}><Trash2 className="h-4 w-4" /></Button> : null}</div></article>) : <p className="p-8 text-center text-sm text-muted-foreground">Nenhum pagamento registrado.</p>}</div></div>
  </section>;
}

export default function FinanceWorkspace() {
  const utils = trpc.useUtils();
  const { can } = useEffectivePermissions();
  const canWrite = can("finance.write");
  const [showCreate, setShowCreate] = useState(false);
  const [financeSection, setFinanceSection] = useState<FinanceSection>("launches");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [paymentInvoiceId, setPaymentInvoiceId] = useState<number | null>(null); const [receivingItemId, setReceivingItemId] = useState<number | null>(null); const [receivingForm, setReceivingForm] = useState({ quantity: "", occurredAt: new Date().toISOString().slice(0, 10) });
  const [filters, setFilters] = useState<{ status: string; dueStartsAt: string; dueEndsAt: string; supplierId: string; operationType?: string; operationId: string }>({ status: "", dueStartsAt: "", dueEndsAt: "", supplierId: "", operationType: "", operationId: "" });
  const [form, setForm] = useState({ supplierId: "", supplierContractId: "", companyId: "", fiscalEntityId: "", invoiceNumber: "", issueDate: "", dueDate: "", amount: "", operationType: "" as "" | "media_campaign" | "action" | "event" | "other", operationId: "", notes: "" });
  const [invoiceItemForm, setInvoiceItemForm] = useState({ kind: "service" as "product" | "service" | "media" | "other", description: "", quantity: "1", unit: "unidade", unitPrice: "", stockItemId: "" });
  const [paymentForm, setPaymentForm] = useState({ amount: "", paidAt: new Date().toISOString().slice(0, 10), method: "PIX", reference: "" });
  const invoices = trpc.finance.listInvoices.useQuery({ status: filters.status ? filters.status as InvoiceStatus : undefined, dueStartsAt: filters.dueStartsAt || undefined, dueEndsAt: filters.dueEndsAt || undefined, supplierId: filters.supplierId ? Number(filters.supplierId) : undefined, operationType: filters.operationType ? filters.operationType as "media_campaign" | "action" | "event" | "other" : undefined, operationId: filters.operationId ? Number(filters.operationId) : undefined });
  const suppliers = trpc.finance.referenceData.useQuery();
  const financeDimensions = trpc.finance.financeDimensions.useQuery();
  const selectedInvoiceCompany = financeDimensions.data?.companies.find(company => String(company.id) === form.companyId);
  const supplierContracts = trpc.finance.listSupplierContracts.useQuery(form.supplierId ? { supplierId: Number(form.supplierId) } : undefined);
  const operations = trpc.finance.operationOptions.useQuery();
  const createInvoice = trpc.finance.createInvoice.useMutation({ onSuccess: () => { toast.success("Nota fiscal registrada."); utils.finance.listInvoices.invalidate(); utils.finance.listSupplierContracts.invalidate(); setShowCreate(false); setForm({ supplierId: "", supplierContractId: "", companyId: "", fiscalEntityId: "", invoiceNumber: "", issueDate: "", dueDate: "", amount: "", operationType: "", operationId: "", notes: "" }); setInvoiceItemForm({ kind: "service", description: "", quantity: "1", unit: "unidade", unitPrice: "", stockItemId: "" }); }, onError: error => toast.error(error.message) });
  const registerPayment = trpc.finance.registerPayment.useMutation({ onSuccess: () => { toast.success("Pagamento registrado."); utils.finance.listInvoices.invalidate(); setPaymentInvoiceId(null); setPaymentForm({ amount: "", paidAt: new Date().toISOString().slice(0, 10), method: "PIX", reference: "" }); }, onError: error => toast.error(error.message) });
  const receiveInvoiceItem = trpc.finance.receiveInvoiceItem.useMutation({ onSuccess: () => { toast.success("Produto recebido e lançado no estoque."); utils.finance.listInvoices.invalidate(); setReceivingItemId(null); setReceivingForm({ quantity: "", occurredAt: new Date().toISOString().slice(0, 10) }); }, onError: error => toast.error(error.message) });
  const uploadDocument = trpc.documents.upload.useMutation({ onSuccess: () => { toast.success("Comprovante anexado com segurança."); utils.finance.listInvoices.invalidate(); }, onError: error => toast.error(error.message) });
  const submit = (event: FormEvent) => { event.preventDefault(); const requiresReference = form.operationType === "media_campaign" || form.operationType === "action" || form.operationType === "event"; const hasItem = invoiceItemForm.description.trim().length > 0; createInvoice.mutate({ supplierId: Number(form.supplierId), supplierContractId: form.supplierContractId ? Number(form.supplierContractId) : null, companyId: form.companyId ? Number(form.companyId) : null, fiscalEntityId: form.fiscalEntityId ? Number(form.fiscalEntityId) : null, invoiceNumber: form.invoiceNumber, issueDate: form.issueDate, dueDate: form.dueDate, amount: Number(form.amount), operationType: form.operationType || null, operationId: requiresReference ? Number(form.operationId) : null, notes: form.notes || undefined, items: hasItem ? [{ kind: invoiceItemForm.kind, description: invoiceItemForm.description, quantity: Number(invoiceItemForm.quantity), unit: invoiceItemForm.unit, unitPrice: Number(invoiceItemForm.unitPrice || form.amount), stockItemId: invoiceItemForm.stockItemId ? Number(invoiceItemForm.stockItemId) : null }] : [] }); };
  const submitPayment = (event: FormEvent) => { event.preventDefault(); if (!paymentInvoiceId) return; registerPayment.mutate({ invoiceId: paymentInvoiceId, paidAt: new Date(`${paymentForm.paidAt}T12:00:00`), amount: Number(paymentForm.amount), method: paymentForm.method, reference: paymentForm.reference || undefined }); };
  const handleFile = async (invoiceId: number, file?: File) => { if (!file) return; if (!acceptedTypes.includes(file.type as (typeof acceptedTypes)[number]) || file.size > 5 * 1024 * 1024) { toast.error("Envie um PDF ou imagem de até 5 MB."); return; } try { uploadDocument.mutate({ entityType: "invoice", entityId: invoiceId, regionalId: null, originalName: file.name, mimeType: file.type as (typeof acceptedTypes)[number], dataBase64: await fileToBase64(file) }); } catch { toast.error("Não foi possível ler o arquivo selecionado."); } };
  return <div className="mx-auto max-w-[1480px]">
    <div className="flex flex-col gap-5 border-b border-border pb-6 sm:flex-row sm:items-end sm:justify-between"><div className="flex gap-4"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-primary text-white shadow-sm"><Landmark className="h-5 w-5" /></span><div><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-foreground">Governança financeira</p><h1 className="mt-1 font-display text-3xl font-semibold tracking-tight text-foreground">Financeiro</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-foreground">Gerencie contratos, ordens de compra, notas fiscais, pagamentos, memória de cálculo e caixa.</p></div></div></div>
    <FinanceSectionNav value={financeSection} onChange={setFinanceSection} />
    {financeSection === "launches" && <><FinanceLaunchesPanel canWrite={canWrite} onNewInvoice={() => setShowCreate(true)} /><InvoicesPaymentsPanel /></>}
    {financeSection === "memory" && <><FinanceMemoryCalculationPanel /><AnnualBudgetPlanner canWrite={canWrite} /></>}
    {financeSection === "cash" && <><CorporateFinancePanel canWrite={canWrite} /><BudgetAndCostsPanel canWrite={canWrite} /><OperationalForecastsPanel onUseForecast={forecast => { setForm({ ...form, supplierId: forecast.suppliers[0] ? String(forecast.suppliers[0].id) : "", supplierContractId: "", invoiceNumber: form.invoiceNumber, issueDate: form.issueDate, dueDate: form.dueDate, amount: String(Number(forecast.estimatedCost)), operationType: forecast.type, operationId: String(forecast.id), notes: form.notes }); setFinanceSection("launches"); setShowCreate(true); }} /></>}
    {showCreate && <Dialog open={showCreate} onOpenChange={setShowCreate}><DialogContent className="max-h-[86vh] max-w-4xl overflow-y-auto"><DialogHeader><DialogTitle>Nova nota fiscal</DialogTitle><DialogDescription>Registre a nota, o fornecedor, o contrato e a operação vinculada para manter o fluxo financeiro rastreável.</DialogDescription></DialogHeader><form onSubmit={submit} className="grid gap-4 rounded-2xl border border-border bg-card p-5 shadow-sm md:grid-cols-6"><div className="md:col-span-2"><Label htmlFor="invoice-supplier">Fornecedor</Label><select id="invoice-supplier" required value={form.supplierId} onChange={event => setForm({ ...form, supplierId: event.target.value, supplierContractId: "" })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Selecionar</option>{suppliers.data?.map(supplier => <option key={supplier.id} value={supplier.id}>{supplier.displayName}</option>)}</select></div><div className="md:col-span-2"><Label htmlFor="invoice-contract">Contrato ou OC</Label><select id="invoice-contract" value={form.supplierContractId} disabled={!form.supplierId} onChange={event => setForm({ ...form, supplierContractId: event.target.value })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Sem contrato vinculado</option>{supplierContracts.data?.map(contract => <option key={contract.id} value={contract.id}>{contract.purchaseOrderCode ? `OC ${contract.purchaseOrderCode} · ` : ""}{contract.contractCode || contract.contractType}</option>)}</select></div><div><Label htmlFor="invoice-company">Empresa operacional</Label><select id="invoice-company" value={form.companyId} onChange={event => setForm({ ...form, companyId: event.target.value, fiscalEntityId: "" })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Selecionar</option>{financeDimensions.data?.companies.map(company => <option key={company.id} value={company.id}>{company.name} · {company.code}</option>)}</select></div><div><Label htmlFor="invoice-fiscal-entity">Empresa fiscal / CNPJ</Label><select id="invoice-fiscal-entity" value={form.fiscalEntityId} onChange={event => setForm({ ...form, fiscalEntityId: event.target.value })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Selecionar</option>{financeDimensions.data?.fiscalEntities.filter(item => !selectedInvoiceCompany?.providerId || item.fiscalEntity.providerId === selectedInvoiceCompany.providerId).map(item => <option key={item.fiscalEntity.id} value={item.fiscalEntity.id}>{item.fiscalEntity.name} · {item.fiscalEntity.cnpj}{item.providerName ? ` · ${item.providerName}` : ""}</option>)}</select></div><div><Label htmlFor="invoice-number">Nº da nota</Label><Input id="invoice-number" required value={form.invoiceNumber} onChange={event => setForm({ ...form, invoiceNumber: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="invoice-amount">Valor (R$)</Label><Input id="invoice-amount" required type="number" min="0.01" step="0.01" value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="invoice-issue">Emissão</Label><Input id="invoice-issue" required type="date" value={form.issueDate} onChange={event => setForm({ ...form, issueDate: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="invoice-due">Vencimento</Label><Input id="invoice-due" required type="date" value={form.dueDate} onChange={event => setForm({ ...form, dueDate: event.target.value })} className="mt-1.5" /></div><div className="md:col-span-2"><Label htmlFor="invoice-operation-type">Vínculo operacional</Label><select id="invoice-operation-type" value={form.operationType} onChange={event => setForm({ ...form, operationType: event.target.value as typeof form.operationType, operationId: "" })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Sem vínculo</option><option value="media_campaign">Campanha de mídia</option><option value="action">Ação de trade</option><option value="event">Evento</option><option value="other">Outra operação</option></select></div>{["media_campaign", "action", "event"].includes(form.operationType) && <div className="md:col-span-2"><Label htmlFor="invoice-operation">Operação</Label><select id="invoice-operation" required value={form.operationId} onChange={event => setForm({ ...form, operationId: event.target.value })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm"><option value="">Selecionar operação</option>{operations.data?.filter(operation => operation.type === form.operationType).map(operation => <option key={`${operation.type}-${operation.id}`} value={operation.id}>{operation.name}</option>)}</select></div>}<div className="md:col-span-6 rounded-xl border border-dashed border-primary/30 bg-primary/[0.03] p-4"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-semibold text-foreground">Itemização da nota</p><p className="mt-1 text-xs text-muted-foreground">Para produtos, vincule o item de estoque e faça o recebimento quando a mercadoria chegar. Para serviços, basta informar a descrição e o valor.</p></div><Badge variant="outline" className="text-[10px]">Opcional</Badge></div><div className="mt-3 grid gap-3 md:grid-cols-6"><div><Label htmlFor="invoice-item-kind">Natureza</Label><select id="invoice-item-kind" value={invoiceItemForm.kind} onChange={event => setInvoiceItemForm({ ...invoiceItemForm, kind: event.target.value as typeof invoiceItemForm.kind, stockItemId: event.target.value === "product" ? invoiceItemForm.stockItemId : "" })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="service">Serviço</option><option value="product">Produto</option><option value="media">Mídia</option><option value="other">Outro</option></select></div><div className="md:col-span-2"><Label htmlFor="invoice-item-description">Descrição do item</Label><Input id="invoice-item-description" value={invoiceItemForm.description} onChange={event => setInvoiceItemForm({ ...invoiceItemForm, description: event.target.value })} placeholder="Ex.: impressão, diária, spot ou material" className="mt-1.5" /></div><div><Label htmlFor="invoice-item-quantity">Quantidade</Label><Input id="invoice-item-quantity" type="number" min="0.01" step="0.01" value={invoiceItemForm.quantity} onChange={event => setInvoiceItemForm({ ...invoiceItemForm, quantity: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="invoice-item-unit">Unidade</Label><Input id="invoice-item-unit" value={invoiceItemForm.unit} onChange={event => setInvoiceItemForm({ ...invoiceItemForm, unit: event.target.value })} className="mt-1.5" /></div><div><Label htmlFor="invoice-item-unit-price">Valor unitário</Label><Input id="invoice-item-unit-price" type="number" min="0" step="0.01" value={invoiceItemForm.unitPrice} onChange={event => setInvoiceItemForm({ ...invoiceItemForm, unitPrice: event.target.value })} placeholder={form.amount || "0,00"} className="mt-1.5" /></div>{invoiceItemForm.kind === "product" && <div className="md:col-span-3"><Label htmlFor="invoice-item-stock">Produto no estoque</Label><select id="invoice-item-stock" required value={invoiceItemForm.stockItemId} onChange={event => setInvoiceItemForm({ ...invoiceItemForm, stockItemId: event.target.value })} className="mt-1.5 h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Selecionar produto</option>{financeDimensions.data?.stock.map(item => <option key={item.id} value={item.id}>{item.name}{item.sku ? ` · ${item.sku}` : ""} · {item.unit}</option>)}</select></div>}</div></div><div className="md:col-span-3"><Label htmlFor="invoice-notes">Observações</Label><Textarea id="invoice-notes" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} className="mt-1.5 min-h-9" /></div><div className="flex items-end"><Button type="submit" disabled={createInvoice.isPending || !suppliers.data?.length} className="w-full bg-primary hover:bg-primary/90">{createInvoice.isPending ? <RefreshCw className="h-4 w-4 animate-spin" /> : "Salvar nota"}</Button></div>{!suppliers.data?.length && <p className="md:col-span-6 flex items-center gap-2 text-xs text-accent-foreground"><AlertCircle className="h-3.5 w-3.5" /> Cadastre um fornecedor em Configurações antes de registrar notas fiscais.</p>}</form></DialogContent></Dialog>}
  </div>;
}
